'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var getOwnPropertyDescriptor = require( '@stdlib/utils/property-descriptor' );
var Fcn = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Fcn, 'function', 'main export is a function' );
	t.end();
});

tape( 'a function instance has a `name` property', function test( t ) {
	var f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( hasProp( f, 'name' ), true, 'has property' );
	t.end();
});

tape( 'the property value is a string', function test( t ) {
	var f;

	f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( typeof f.name, 'string', 'returns expected value' );
	t.end();
});

tape( 'functions created using the `Function` constructor have the name `anonymous`', function test( t ) {
	var f;

	f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( f.name, 'anonymous', 'returns expected value' );
	t.end();
});

tape( 'the `name` property is not writable', function test( t ) {
	var desc;
	var f;

	f = new Fcn( 'x', 'y', 'return x + y' );
	desc = getOwnPropertyDescriptor( f, 'name' );
	t.strictEqual( desc.writable, false, 'is not writable' );
	t.end();
});
